# SPDX-License-Identifier: MIT
# Turns `spike` stdout + .bin files into a C header (see gen-shaders.sh).
import os, re, sys
ARCH = os.environ.get("GEN_ARCH", "11")
out, *items = sys.argv[1:]          # items: name:stdout.txt:bin
L = ["/* SPDX-License-Identifier: MIT */",
     "/* GENERATED by driver/compiler-spike/gen-shaders.sh -- do not edit. Valhall v" + ARCH + " binaries from Mesa's offline compiler. */",
     "#pragma once", "#include <stdint.h>", ""]
for it in items:
    name, txt, binp = it.split(":")
    meta = {}; fau = []; slots = []
    for ln in open(txt):
        if ln.startswith(("META ", "META_VS ")):
            for k, v in re.findall(r"(\w+)=(\S+)", ln): meta[k] = int(v, 0)
        elif ln.startswith("FAU "):
            _, i, v = ln.split(); fau.append((int(i), int(v, 0)))
        elif ln.startswith("VSLOT "):
            slots.append(ln.strip())
    data = open(binp, "rb").read()
    L.append(f"static const uint8_t {name}_bin[{len(data)}] __attribute__((aligned(16))) = {{")
    for i in range(0, len(data), 16):
        L.append("  " + ",".join(f"0x{b:02x}" for b in data[i:i+16]) + ",")
    L.append("};")
    for k, v in meta.items():
        L.append(f"#define {name.upper()}_{k.upper()} {v}ull" if k.endswith("preload") else f"#define {name.upper()}_{k.upper()} {v}")
    L.append(f"/* promoted-immediate FAU words (32-bit word index, value); words [0,{meta['fau_reserved']}) are driver-owned */")
    L.append(f"#define {name.upper()}_NIMM {len(fau)}")
    L.append(f"static const uint32_t {name}_imm[][2] = {{" + (",".join("{%d,0x%08x}" % f for f in fau) if fau else "{0,0}") + "};")
    for s in slots: L.append("/* " + s + " */")
    L.append("")
open(out, "w").write("\n".join(L) + "\n")
